use serde::{Deserialize, Serialize};
use std::collections::HashMap;

# [test] fn test_next_point () { let sm = SourceMap :: new (FilePathMapping :: empty ()) ; sm . new_source_file (PathBuf :: from ("example.rs") . into () , "a…b" . to_string ()) ; let span = DUMMY_SP ; let span = sm . next_point (span) ; assert_eq ! (span . lo () . 0 , 0) ; assert_eq ! (span . hi () . 0 , 0) ; let span = Span :: with_root_ctxt (BytePos (0) , BytePos (1)) ; assert_eq ! (sm . span_to_snippet (span) , Ok ("a" . to_string ())) ; let span = sm . next_point (span) ; assert_eq ! (sm . span_to_snippet (span) , Ok ("…" . to_string ())) ; assert_eq ! (span . lo () . 0 , 1) ; assert_eq ! (span . hi () . 0 , 4) ; let span = Span :: with_root_ctxt (BytePos (1) , BytePos (1)) ; let span = sm . next_point (span) ; assert_eq ! (span . lo () . 0 , 1) ; assert_eq ! (span . hi () . 0 , 4) ; let span = Span :: with_root_ctxt (BytePos (1) , BytePos (4)) ; let span = sm . next_point (span) ; assert_eq ! (span . lo () . 0 , 4) ; assert_eq ! (span . hi () . 0 , 5) ; let span = Span :: with_root_ctxt (BytePos (4) , BytePos (5)) ; let span = sm . next_point (span) ; assert_eq ! (span . lo () . 0 , 5) ; assert_eq ! (span . hi () . 0 , 6) ; assert ! (sm . span_to_snippet (span) . is_err ()) ; let span = Span :: with_root_ctxt (BytePos (5) , BytePos (5)) ; let span = sm . next_point (span) ; assert_eq ! (span . lo () . 0 , 5) ; assert_eq ! (span . hi () . 0 , 6) ; assert ! (sm . span_to_snippet (span) . is_err ()) ; }